func runSuppressions(args []string) {
	if len(args) < 1 {
		fmt.Fprintln(os.Stderr, "usage: mevwatch suppressions <list|register|revoke> ...")
		os.Exit(2)
	}
	switch args[0] {
	case "list":
		if len(args) != 2 {
			fmt.Fprintln(os.Stderr, "usage: mevwatch suppressions list <archive-dir>")
			os.Exit(2)
		}
		conds, err := mevwatch.ListSuppressions(args[1])
		if err != nil {
			fmt.Fprintf(os.Stderr, "suppressions list: %v\n", err)
			os.Exit(1)
		}
		writeJSON(conds)
	case "register":
		if len(args) != 3 {
			fmt.Fprintln(os.Stderr, "usage: mevwatch suppressions register <archive-dir> <spec-file>")
			os.Exit(2)
		}
		var raw []byte
		var err error
		if args[2] == "-" {
			raw, err = io.ReadAll(os.Stdin)
		} else {
			raw, err = os.ReadFile(args[2])
		}
		if err != nil {
			fmt.Fprintf(os.Stderr, "suppressions register: %v\n", err)
			os.Exit(1)
		}
		cond, created, err := mevwatch.RegisterSuppression(args[1], raw)
		if err != nil {
			fmt.Fprintf(os.Stderr, "suppressions register: %v\n", err)
			os.Exit(1)
		}
		writeJSON(struct {
			Created     bool                 `json:"created"`
			Suppression mevwatch.Suppression `json:"suppression"`
		}{Created: created, Suppression: cond})
	case "revoke":
		if len(args) != 3 {
			fmt.Fprintln(os.Stderr, "usage: mevwatch suppressions revoke <archive-dir> <condition-id>")
			os.Exit(2)
		}
		cond, changed, err := mevwatch.RevokeSuppression(args[1], args[2])
		if err != nil {
			fmt.Fprintf(os.Stderr, "suppressions revoke: %v\n", err)
			os.Exit(1)
		}
		writeJSON(struct {
			Changed     bool                 `json:"changed"`
			Suppression mevwatch.Suppression `json:"suppression"`
		}{Changed: changed, Suppression: cond})
	default:
		fmt.Fprintf(os.Stderr, "unknown suppressions subcommand %q\n", args[0])
		usage()
		os.Exit(2)
	}
}

