3	// Regression coverage for the single-block rule comparison behind the
4	// `compare` entry. These tests pin behaviour end to end on the in-package
5	// API: the archived side keeps the version that judged it at archive time,
6	// the candidate side is judged strictly under the version named in the
7	// call (never the currently enabled one), diffs are split per victim
8	// transaction, ordering and evidence are preserved, the query is read
9	// only, and pre-version legacy archives are interpreted as builtin.
10	
11	import (
12		"encoding/json"
13		"errors"
14		"os"
15		"path/filepath"
16		"reflect"
17		"sort"
18		"strings"
19		"testing"
20	)
21	
22	const (
23		// archivedVersion is the version under which the fixture block is
24		// archived: sandwich severity 4, displacement severity 1 with
25		// multiplier 3.
26		archivedVersionSpec = `{"id":"archA","rules":{"sandwich":{"enabled":true,"severity":4},"displacement":{"enabled":true,"severity":1,"multiplier":3}}}`
27		// enabledVersion is enabled in the archive afterwards but must never
28		// leak into either side of a comparison. Its judgments are markedly
29		// different: sandwich severity 5, displacement severity 5 with
30		// multiplier 4.
31		enabledVersionSpec = `{"id":"liveB","rules":{"sandwich":{"enabled":true,"severity":5},"displacement":{"enabled":true,"severity":5,"multiplier":4}}}`
32		// candidateVersion is the version named at compare time: sandwich
33		// disabled, displacement severity 4 with the builtin multiplier 2.
34		candidateVersionSpec = `{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}`
35		// twinVersion carries the builtin parameters under another id, so a
36		// comparison produces identical conclusions and an empty diff.
37		twinVersionSpec = `{"id":"twin","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
38	)
39	
40	// cmpSwap builds one swap record map; In and Out are fixed because the
41	// detection rules never read them, while every numeric field is explicit.
42	func cmpSwap(tx, pool, trader string, gas int64, index int) map[string]any {
43		return map[string]any{
44			"TxHash": tx, "Pool": pool, "Trader": trader,
45			"In": 1, "Out": 1, "GasPrice": gas, "Index": index,
46		}
47	}
48	
49	func cmpBlockLine(chain, hash string, number int64, swaps ...map[string]any) string {
50		block := map[string]any{
51			"chainId": chain, "blockHash": hash, "blockNumber": number, "swaps": swaps,
52		}
53		raw, err := json.Marshal(block)
54		if err != nil {
55			panic(err)
56		}
57		return string(raw)
58	}
59	
60	// compareFixtureInput covers every diff shape in one archived block:
61	//
62	//	p1 0xa0f/0xa0v/0xa0b  sandwich sev4 under archA -> displacement sev4
63	//	                      under candC (kind change, severity identical);
64	//	p2 0xb0f/0xb0v/0xb0z  displacement sev1 (mult 3) -> sev4 (mult 2),
65	//	                      a severity-only change;
66	//	p3 0xc0f/0xc0v       no conclusion under either version, no diff;
67	//	p4 0xd0f/0xd0v       absent under archA (25 <= 30), displacement
68	//	                      sev4 under candC (25 > 20): added;
69	//	p5 0xe0f/0xe0v/0xe0b sandwich sev4 under archA (15/11 bracket 10),
70	//	                      nothing under candC (sandwich off, 15 <= 20):
71	//	                      removed.
72	func compareFixtureInput() string {
73		lines := []string{
74			cmpBlockLine("1", "0xblk", 100,
75				cmpSwap("0xa0f", "p1", "bot", 90, 0),
76				cmpSwap("0xa0v", "p1", "user", 10, 1),
77				cmpSwap("0xa0b", "p1", "bot", 80, 2),
78				cmpSwap("0xb0f", "p2", "w", 40, 3),
79				cmpSwap("0xb0v", "p2", "u", 10, 4),
80				cmpSwap("0xb0z", "p2", "z", 10, 5),
81				cmpSwap("0xc0f", "p3", "w", 15, 6),
82				cmpSwap("0xc0v", "p3", "u", 10, 7),
83				cmpSwap("0xd0f", "p4", "w", 25, 8),
84				cmpSwap("0xd0v", "p4", "u", 10, 9),
85				cmpSwap("0xe0f", "p5", "bot", 15, 10),
86				cmpSwap("0xe0v", "p5", "user", 10, 11),
87				cmpSwap("0xe0b", "p5", "bot", 11, 12),
88			),
89			// Decoy: same height, different block hash on the same chain.
90			cmpBlockLine("1", "0xother", 100,
91				cmpSwap("0xzz1", "pz", "tz", 999, 0),
92				cmpSwap("0xzz2", "pz", "tz2", 998, 1),
93			),
94			// Decoy: same height and hash on another chain.
95			cmpBlockLine("2", "0xblk", 100,
96				cmpSwap("0xqq1", "pq", "tq", 777, 0),
97				cmpSwap("0xqq2", "pq", "tq2", 776, 1),
98			),
99		}
100		return strings.Join(lines, "\n") + "\n"
101	}
102	
103	// setupCompareArchive writes the fixture to a real (then deleted) input
104	// file, archives it under archA, registers candC and enables liveB. The
105	// returned input path has already been removed, proving compare needs no
106	// source file.
107	func setupCompareArchive(t *testing.T) string {
108		t.Helper()
109		dir := t.TempDir()
110		inputPath := filepath.Join(t.TempDir(), "blocks.jsonl")
111		if err := os.WriteFile(inputPath, []byte(compareFixtureInput()), 0o644); err != nil {
112			t.Fatal(err)
113		}
114		register(t, dir, archivedVersionSpec)
115		register(t, dir, enabledVersionSpec)
116		register(t, dir, candidateVersionSpec)
117		register(t, dir, twinVersionSpec)
118		if reports, err := ReplayFileWithVersion(inputPath, dir, "archA"); err != nil {
119			t.Fatalf("ReplayFileWithVersion: %v", err)
120		} else if len(reports) != 3 {
121			t.Fatalf("got %d reports, want 3", len(reports))
122		}
123		if _, err := EnableVersion(dir, "liveB"); err != nil {
124			t.Fatalf("EnableVersion: %v", err)
125		}
126		if err := os.Remove(inputPath); err != nil {
127			t.Fatal(err)
128		}
129		return dir
130	}
131	
132	func mustRuleVersion(t *testing.T, spec string) RuleVersion {
133		t.Helper()
134		v, err := ParseRuleVersion([]byte(spec))
135		if err != nil {
136			t.Fatalf("ParseRuleVersion: %v", err)
137		}
138		return v
139	}
140	
141	func TestCompareRegressionFullDiff(t *testing.T) {
142		dir := setupCompareArchive(t)
143	
144		result, err := Compare(dir, "1", "0xblk", "candC")
145		if err != nil {
146			t.Fatalf("Compare: %v", err)
147		}
148	
149		// Block identity is exactly the selected chain/block; the same-height
150		// same-chain decoy and the same-hash other-chain decoy never mix in.
151		if result.ChainID != "1" || result.BlockHash != "0xblk" || result.BlockNumber != 100 {
152			t.Fatalf("block identity wrong: %s/%s @%d", result.ChainID, result.BlockHash, result.BlockNumber)
153		}
154	
155		// Each side carries its own full parameters: the archived conclusion
156		// uses archA even though liveB is now enabled, and the candidate side
157		// uses candC rather than the enabled liveB.
158		if !reflect.DeepEqual(result.OriginalVersion, mustRuleVersion(t, archivedVersionSpec)) {
159			t.Fatalf("original version = %+v, want archA", result.OriginalVersion)
160		}
161		if !reflect.DeepEqual(result.ComparedVersion, mustRuleVersion(t, candidateVersionSpec)) {
162			t.Fatalf("compared version = %+v, want candC", result.ComparedVersion)
163		}
164		if result.ComparedVersion.ID == "liveB" ||
165			result.ComparedVersion.Rules.Sandwich.Enabled ||
166			result.ComparedVersion.Rules.Displacement.Multiplier != 2 {
167			t.Fatalf("candidate side leaked the enabled version: %+v", result.ComparedVersion)
168		}
169	
170		// Original findings: severity desc, hash asc within a severity.
171		// p1 and p5 are both sandwiches sev4 (hash asc: 0xa0v before 0xe0v),
172		// the p2 displacement sev1 comes last.
173		wantOrig := []struct {
174			tx       string
175			kind     string
176			severity int
177			evidence int
178		}{
179			{"0xa0v", "sandwich", 4, 3},
180			{"0xe0v", "sandwich", 4, 3},
181			{"0xb0v", "displacement", 1, 2},
182		}
183		if len(result.OriginalFindings) != len(wantOrig) {
184			t.Fatalf("original findings = %+v", result.OriginalFindings)
185		}
186		for i, w := range wantOrig {
187			got := result.OriginalFindings[i]
188			if got.TxHash != w.tx || got.Kind != w.kind || got.Severity != w.severity || len(got.Evidence) != w.evidence {
189				t.Fatalf("original[%d] = %+v, want %+v", i, got, w)
190			}
191		}
192	
193		// Candidate findings: all displacement sev4 under candC (sandwich is
194		// off), hash asc. In particular 0xa0v is a displacement here, so the
195		// enabled liveB (which would still flag it as a sandwich sev5) was
196		// never consulted.
197		wantComp := []struct {
198			tx       string
199			evidence int
200		}{
201			{"0xa0v", 2},
202			{"0xb0v", 2},
203			{"0xd0v", 2},
204		}
205		if len(result.ComparedFindings) != len(wantComp) {
206			t.Fatalf("compared findings = %+v", result.ComparedFindings)
207		}
208		for i, w := range wantComp {
209			got := result.ComparedFindings[i]
210			if got.TxHash != w.tx || got.Kind != "displacement" || got.Severity != 4 || len(got.Evidence) != w.evidence {
211				t.Fatalf("compared[%d] = %+v, want tx %s displacement sev4 with %d evidence", i, got, w.tx, w.evidence)
212			}
213		}
214	
215		// Diffs are per victim transaction with the expected shapes.
216		if len(result.Added) != 1 || result.Added[0].TxHash != "0xd0v" {
217			t.Fatalf("added = %+v", result.Added)
218		}
219		if len(result.Removed) != 1 || result.Removed[0].TxHash != "0xe0v" {
220			t.Fatalf("removed = %+v", result.Removed)
221		}
222		if len(result.Changed) != 2 {
223			t.Fatalf("changed = %+v", result.Changed)
224		}
225		if result.Changed[0].TxHash != "0xa0v" || result.Changed[1].TxHash != "0xb0v" {
226			t.Fatalf("changed not hash-sorted: %+v", result.Changed)
227		}
228	
229		// Sandwich -> displacement for one transaction stays a single change
230		// carrying both conclusions; it must never be split into add+remove.
231		kindChange := result.Changed[0]
232		if kindChange.Original.Kind != "sandwich" || kindChange.Original.Severity != 4 ||
233			len(kindChange.Original.Evidence) != 3 {
234			t.Fatalf("kind change original side wrong: %+v", kindChange.Original)
235		}
236		if kindChange.Compared.Kind != "displacement" || kindChange.Compared.Severity != 4 ||
237			len(kindChange.Compared.Evidence) != 2 {
238			t.Fatalf("kind change compared side wrong: %+v", kindChange.Compared)
239		}
240		// Severity-only change likewise keeps both sides.
241		sevChange := result.Changed[1]
242		if sevChange.Original.Kind != "displacement" || sevChange.Original.Severity != 1 ||
243			sevChange.Compared.Kind != "displacement" || sevChange.Compared.Severity != 4 {
244			t.Fatalf("severity change wrong: %+v", sevChange)
245		}
246	
247		// The victim flagged identically under both versions (none in this
248		// block) would be absent from every diff list; p3's swaps stay only
249		// in the full evidence record.
250	
251		// Full archived swap records survive: all 13, in Index order, with
252		// every original field, including swaps that took no part in any
253		// conclusion (the sandwich backs, 0xb0z and the whole p3 pair).
254		if len(result.Swaps) != 13 {
255			t.Fatalf("swaps = %+v", result.Swaps)
256		}
257		wantSwap := Swap{TxHash: "0xb0z", Pool: "p2", Trader: "z", In: 1, Out: 1, GasPrice: 10, Index: 5}
258		if !reflect.DeepEqual(result.Swaps[5], wantSwap) {
259			t.Fatalf("swap record not preserved: got %+v", result.Swaps[5])
260		}
261		for i, s := range result.Swaps {
262			if s.Index != i {
263				t.Fatalf("swaps not in index order at %d: %+v", i, s)
264			}
265		}
266	
267		// Evidence inside conclusions keeps raw tx/pool/trader/amount/gas/index.
268		ev := result.OriginalFindings[0].Evidence[0]
269		if ev != (Swap{TxHash: "0xa0f", Pool: "p1", Trader: "bot", In: 1, Out: 1, GasPrice: 90, Index: 0}) {
270			t.Fatalf("sandwich evidence damaged: %+v", ev)
271		}
272	}
