606	// severity 4 multiplier 2) and twin, and archives one block under candC
607	// whose adjacent same-pool swaps hit displacement with no sandwich — the
608	// exact shape that crashed detection when the stored multiplier decayed
609	// to zero.
610	func setupCorruptCompareArchive(t *testing.T) string {
611		t.Helper()
612		dir := t.TempDir()
613		register(t, dir, candidateVersionSpec)
614		register(t, dir, twinVersionSpec)
615		input := cmpBlockLine("1", "0xblk", 7,
616			cmpSwap("0xf", "p1", "w", 40, 0),
617			cmpSwap("0xv", "p1", "u", 10, 1),
618		)
