	if _, err := ReplayWithVersion(strings.NewReader(replayCorruptInput), dir, "candC"); !errors.Is(err, ErrCorruptVersion) {
		t.Fatalf("explicit-version replay error = %v, want ErrCorruptVersion", err)
	}

